"""RetinaScan XAI: Kaggle GPU runner (generated by kaggle/build_kernel.py; do not edit the copy in kaggle/kernel/).

Pipeline: verify + cache + dedupe + split -> train -> calibrate/evaluate -> train-split index.
Outputs land in /kaggle/working/artifacts (download with `kaggle kernels output`).
"""
import base64
import io
import json
import os
import shutil
import subprocess
import sys
import tarfile
import time
from pathlib import Path

STAGE = "__STAGE__"
CONFIG = json.loads(r'''__CONFIG__''')
CODE_B64 = "__CODE_B64__"

WORK = Path("/kaggle/working")
ART = WORK / "artifacts"
CODE = Path("/tmp/rs_code")
CACHE = Path("/tmp/rs_cache")
RUN = Path("/tmp/rs_run")


def sh(args, log):
    print("$", " ".join(map(str, args)), flush=True)
    with open(log, "a") as f:
        p = subprocess.Popen([sys.executable, "-u", *map(str, args)], cwd=CODE, stdout=subprocess.PIPE,
                             stderr=subprocess.STDOUT, text=True)
        for line in p.stdout:
            print(line, end="", flush=True)
            f.write(line)
        if p.wait() != 0:
            raise SystemExit(f"step failed: {args[0]} (exit {p.returncode}); see {log}")


def find_aptos():
    for csv in Path("/kaggle/input").rglob("train.csv"):
        if (csv.parent / "train_images").is_dir():
            return csv, csv.parent / "train_images"
    raise SystemExit("APTOS train.csv + train_images not found under /kaggle/input. "
                     "Is the competition attached and its rules accepted?")


def main():
    t0 = time.time()
    for d in (ART, CODE, CACHE, RUN):
        d.mkdir(parents=True, exist_ok=True)
    tarfile.open(fileobj=io.BytesIO(base64.b64decode(CODE_B64))).extractall(CODE)
    log = ART / "pipeline.log"
    c = CONFIG
    csv, img_dir = find_aptos()
    print(f"stage={STAGE} aptos={csv.parent} config={c}", flush=True)
    try:
        import torch
        print("cuda:", torch.cuda.is_available(), torch.cuda.get_device_name(0) if torch.cuda.is_available() else "-")
    except Exception as e:  # noqa: BLE001
        print("torch check failed:", e)

    lim = ["--limit", str(c["limit"])] if c.get("limit") else []
    sh(["prepare_data.py", "--csv", csv, "--img_dir", img_dir, "--cache_dir", CACHE, "--out_dir", ART,
        "--size", c["size"], "--workers", c["workers"], *lim, *(["--no_clahe"] if not c["clahe"] else [])], log)
    sh(["train.py", "--splits", ART / "splits.csv", "--cache_dir", CACHE, "--out", RUN, "--arch", c["arch"],
        "--size", c["size"], "--clahe", int(c["clahe"]), "--epochs", c["epochs"], "--bs", c["bs"], "--lr", c["lr"],
        "--workers", c["workers"], "--version", c["version"],
        *(["--limit", str(c["train_limit"])] if c.get("train_limit") else [])], log)
    shutil.copy(RUN / "best.pt", ART / "model.pt")
    for f in ("history.json", "train_config.json", "train_summary.json"):
        shutil.copy(RUN / f, ART / f)
    sh(["evaluate.py", "--ckpt", ART / "model.pt", "--splits", ART / "splits.csv", "--cache_dir", CACHE,
        "--out", ART, "--target_sens", c["target_sens"], "--target_coverage", c["target_coverage"],
        "--workers", c["workers"], *(["--no_ci"] if c.get("no_ci") else [])], log)
    sh(["embed.py", "--ckpt", ART / "model.pt", "--splits", ART / "splits.csv", "--cache_dir", CACHE,
        "--out", ART, "--workers", c["workers"]], log)
    # Many small files download slowly; ship thumbnails as one archive.
    shutil.make_archive(str(ART / "thumbs"), "zip", ART / "thumbs")
    shutil.rmtree(ART / "thumbs")
    print(f"ALL DONE in {(time.time() - t0) / 60:.1f} min; artifacts: {sorted(p.name for p in ART.iterdir())}",
          flush=True)


if __name__ == "__main__":
    main()
